    /// <summary>The team races (and pairs-only or five-member races), as listed in the booklet.</summary>
    public static readonly Entry[] Core = new[]
    {
        // ── Bending family ─────────────────────────────────────────────────
        new Entry("Bending", "Bending",
            "Each rider rides down and back through five bending poles, then hands the baton to the next rider.",
            "Five Bending Poles are placed in a line 7 to 9 m apart, with Pole 1 14 m from the Start/Finish Line. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a Baton, rides down and back through the Bending Poles. After crossing the Start/Finish Line, they hand the Baton to Number Two. Numbers Two, Three and Four ride down and back through the Bending Poles in the same way, in succession. The winning team is the one whose Number Four is first over the Start/Finish Line, mounted and carrying the Baton. Any pole that is knocked down must be replaced by the rider concerned, who must go back and resume the race from the point where the pole was knocked down. They may resume by bending either side of the position of the pole, not necessarily on the same bend as before. If a Bending Pole is missed, the rider can correct this by returning to the missed pole and continuing from there, on either side of it. Line Stewards will not signal unless a pole is broken or lying flat on the ground.",
            BendingDiagram),

        new Entry("Mug Changes", "Mug",
            "Three mugs are moved along a line of four poles, with Numbers One and Three working up the arena and Numbers Two and Four working back.",
            "Four Bending Poles are placed in a line 7 to 9 m apart, with mugs on Poles 2 and 4. Numbers One and Three are mounted at the Start/Finish End; Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One, carrying a mug, rides to Pole 1 and places the mug on it, collects the mug from Pole 2 and places it on Pole 3, then collects the mug from Pole 4 and hands it to Number Two behind the Changeover Line. Number Two places the mug on Pole 4, collects the mug from Pole 3 and places it on Pole 2, then collects the mug from Pole 1 and hands it to Number Three behind the Start/Finish Line. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four is first over the Start/Finish Line, mounted and carrying the mug, with mugs on Poles 2 and 4. Any pole that is knocked over must be corrected by the rider concerned and be upright at the end of the race. Mugs must be placed on each pole in the correct order. If a mug falls or is missed, the rider must replace it before continuing. If the next mug has already been moved, the rider must first put that mug back on the correct pole and then correct the first error.",
            MugChangesDiagram),

        new Entry("Two Mug", "Mug",
            "Two mugs start on Poles 1 and 3 and are moved up and down a line of four poles.",
            "Four Bending Poles are placed in a line 7 to 9 m apart, with mugs on Poles 1 and 3. Numbers One and Three are mounted at the Start/Finish End; Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One rides down the arena, moves the mug from Pole 1 to Pole 2, then the mug from Pole 3 to Pole 4, and rides across the Changeover Line. Number Two rides back down the arena, moves the mug from Pole 4 to Pole 3, then the mug from Pole 2 to Pole 1, and crosses the Start/Finish Line. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four crosses the Start/Finish Line first with mugs on Poles 1 and 3. Mugs must be placed on each pole in the correct order. If a mug falls or is missed, the rider must replace it before continuing. If the next mug has already been moved, the rider must first put that mug back on the correct pole and then correct the first error.",
            TwoMugDiagram),

        new Entry("Three Mug", "Mug",
            "Three mugs start on Poles 2, 3 and 4 and are moved along the line one pole at a time.",
            "Four Bending Poles are placed in a line 7 to 9 m apart, with mugs on Poles 2, 3 and 4. All four riders are mounted at the Start/Finish End. On the signal to start, Number One rides forward and moves the mug from Pole 2 to Pole 1, then the mug from Pole 3 to Pole 2, then the mug from Pole 4 to Pole 3, and rides back over the Start/Finish Line. Number Two rides down the arena and moves the mug from Pole 3 to Pole 4, then the mug from Pole 2 to Pole 3, then the mug from Pole 1 to Pole 2, and rides back over the Start/Finish Line. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four is first across the Start/Finish Line with mugs on Poles 2, 3 and 4. Mugs must be placed on each pole in the correct order. If a mug falls or is missed, the rider must replace it before continuing. If the next mug has already been moved, the rider must first put that mug back on the pole it was taken from and then correct the first error.",
            ThreeMugDiagram),

        new Entry("Five Mug – Pole Specific", "Mug",
            "Mugs go inverted on Poles 2 to 5 in turn, then Number Four puts the EGUK logo mug on Pole 1.",
            "Five Bending Poles are put up 7 to 9 m apart, with Pole 1 the nearest to the Start/Finish Line. A Table is placed 3 m behind the Changeover Line. All four riders are mounted at the Start/Finish End. The team has five mugs. Four of them, one of which carries the EGUK logo, are placed inverted on the Table, with the EGUK mug at 8 o'clock (left front) looking from the Start/Finish Line; the fifth is carried by Number One. On the signal to start, Number One rides to Pole 2 and places the mug inverted on top, rides to the Table, picks up any mug except the EGUK mug and rides back to hand it to Number Two behind the Start/Finish Line. Number Two does the same on Pole 3, Number Three on Pole 4, with Number Three picking up the remaining mug without the logo. Number Four places the mug inverted on Pole 5, rides to the Table, picks up the EGUK mug, rides back down the arena, places it on top of Pole 1 and rides across the Start/Finish Line. The winning team is the one whose Number Four is first over the Start/Finish Line with a mug on each pole and the EGUK mug on Pole 1. Riders may ride straight and need not bend through the poles. Any mug knocked off the Table must be replaced inverted by the rider concerned; the EGUK mug may be replaced inverted anywhere on the Table.",
            FiveMugDiagram),

        new Entry("One Mug Race (Junior)", "Mug",
            "Junior version: one mug is moved between Pole 2 and Pole 3 by the four riders in turn.",
            "A line of four Bending Poles is erected 7 to 9 m apart, with a mug on top of Pole 2. Numbers One and Three are mounted at the Start/Finish End; Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One rides down the arena, moves the mug from Pole 2 to Pole 3 and rides across the Changeover Line. Number Two rides back down the arena, moves the mug from Pole 3 to Pole 2 and crosses the Start/Finish Line. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four is first across the Start/Finish Line with the mug on Pole 2.",
            OneMugJuniorDiagram),

        new Entry("Three Mug and Table (Pairs)", "Mug",
            "Pairs version: three mugs are shuttled between a table and the poles, always inverted, and riders ride straight.",
            "Five Bending Poles are placed in a line 7 to 9 m apart, with Pole 1 nearest the Start/Finish Line. A Table is placed 3 m behind the Changeover Line. Both riders form up at the Start/Finish End. Each pair has three mugs: two are placed inverted on the Table behind the Changeover Line and the third is carried by Number One. On the signal to start, Number One rides and places the mug inverted on top of a pole, then rides to the Table, picks up another mug and returns to hand it to Number Two behind the Start/Finish Line. Number Two rides down the arena, places the mug inverted on top of Pole 5, collects the final mug from the Table and returns to place it on Pole 1 before crossing the Start/Finish Line. Riders may ride straight and need not bend through the poles. Any mug knocked off the Table must always be replaced inverted.",
            ThreeMugAndTablePairsDiagram),

        // ── Ball / Cone family ────────────────────────────────────────────
        new Entry("Ball and Cone", "Ball",
            "Move a tennis ball back and forth between two cones level with Poles 1 and 4.",
            "There are two Ball Cones for each team, placed level with Poles 1 and 4, with a tennis ball on the Ball Cone level with Pole 4. Numbers One and Three are mounted behind the Start/Finish Line; Numbers Two and Four are mounted behind the Changeover Line. On the signal to start, Number One, carrying a tennis ball, rides to the cone level with Pole 1 and places the ball on it. They then ride to the cone level with Pole 4, collect the ball and cross the Changeover Line to hand it to Number Two. Number Two places the ball on the cone level with Pole 4, rides to the cone level with Pole 1, collects the ball and crosses the Start/Finish Line to hand it to Number Three. Numbers Three and Four complete the race in a similar manner. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the tennis ball, with the other tennis ball on the Ball Cone level with Pole 4. If a cone is knocked over or a ball is dropped, the General Rules apply.",
            BallAndConeDiagram),

        new Entry("Ball and Flag", "Ball",
            "Combine ball-on-cone with flag-in-cone across two stations.",
            "Ball Cone level with Pole 1 and Flag Cone (with flag) level with Pole 4. Numbers 1 & 3 at Start/Finish, 2 & 4 at Changeover. Number One places the ball on Pole 1 cone, collects the flag from Pole 4 cone and hands to Number Two. Number Two replaces the flag in the cone, collects the ball and hands to Number Three. Numbers 3 & 4 repeat. Winner: Number Four first over the line carrying the ball with the flag in the Flag Cone.",
            BallAndFlagDiagram),

        new Entry("Ball and Racquet", "Ball",
            "Carry a tennis ball on a racquet up or down a line of four bending poles and hand the racquet on.",
            "A line of four Bending Poles is placed 7 to 9 m apart. Each team has a tennis racquet and a tennis ball. Numbers One and Three are at the Start/Finish End; Numbers Two and Four are at the Changeover End. On the signal to start, Number One, carrying the tennis ball on the head of the racquet, rides up the arena through the line of Bending Poles and hands the racquet to Number Two behind the Changeover Line. Number Two repeats the process, handing over to Number Three behind the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two. Each racquet has a crosspiece through the centre of the handle, and the rider's hand must be behind the crosspiece at all times during the race and at the changeover.",
            BallAndRacquetDiagram),

        new Entry("Ball & Racquet (Old Version)", "Ball",
            "Balance a tennis ball on a racquet through three bending poles.",
            "Three Bending Poles 7–9 m apart per team; all riders form up behind the Start/Finish Line. Number One carries a racquet (with a cross piece through the centre of the handle) holding a tennis ball. The rider's hand must stay behind the cross piece and the ball must not be touched by hand, except when correcting an error. Number One rides up and back through the poles and hands the racquet and ball to Number Two behind the Start/Finish Line; Numbers Two, Three and Four repeat. If the ball is dropped the rider picks it up, mounted or dismounted, and resumes from where it fell. If it is dropped at the handover, the incoming rider may dismount and put it on the next rider's racquet, behind the Start/Finish Line. Any pole knocked down must be replaced by the rider concerned. Winner: Number Four first over the Start/Finish Line carrying the ball on the racquet.",
            BallAndRacquetOldDiagram),

        new Entry("Ball and Socket", "Ball",
            "Place a ball into a high socket board at the changeover, then return collecting from a cone.",
            "A line of four Ball Cones is placed level with Poles 1, 2, 3 and 4, with a tennis ball on top of each cone. A Bending Pole topped with a Socket Board with four sockets, each large enough to hold a tennis ball, is placed 3 m beyond the Changeover Line. Number One, carrying a tennis ball, rides to the Changeover End and places it in one of the sockets. Number One then rides back down the arena to the Start/Finish End, collecting a tennis ball from any Ball Cone on the way and handing it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One in turn. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the last tennis ball. If a rider makes a genuine attempt to place a ball in a socket and drops it, they may dismount and place it in the socket dismounted. If, in placing their ball, a rider knocks out a ball that a previous rider has placed in the Socket Board, they must replace it, mounted or dismounted.",
            BallAndSocketDiagram),

        new Entry("Ball and Socket – Cone Specific", "Ball",
            "As Ball and Socket, but each rider must collect from a set cone: Pole 4, then 3, 2 and 1.",
            "A line of four Ball Cones is placed level with Poles 1, 2, 3 and 4, with a tennis ball on top of each cone. A Bending Pole topped with a Socket Board with four sockets, each large enough to hold a tennis ball, is placed 3 m beyond the Changeover Line. Number One, carrying a tennis ball, rides to the Changeover End and places it in one of the sockets, then rides back down the arena, collecting the ball from the Ball Cone level with Pole 4 and handing it to Number Two behind the Start/Finish Line. Number Two places the ball in one of the sockets, then rides back collecting the ball from the cone level with Pole 3 and hands it to Number Three. Number Three places the ball in a socket, then collects the ball from the cone level with Pole 2 and hands it to Number Four. Number Four places the ball in the remaining socket, then rides back down the arena and over the Start/Finish Line, collecting the ball from the cone level with Pole 1 on the way. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the last tennis ball, with a ball in each socket of the Socket Board. If a rider makes a genuine attempt to place a ball in a socket and drops it, they may dismount and place it in the socket dismounted. If, in placing their ball, a rider knocks out a ball that a previous rider has placed in the Socket Board, they must replace it, mounted or dismounted.",
            BallAndSocketDiagram),

        new Entry("Ball and Bucket", "Ball",
            "Drop tennis balls into a bucket on the Centre Line, collecting a fresh ball from behind the Changeover Line each time.",
            "Four tennis balls for each team are placed within a marked circle 3 m behind the Changeover Line. A row of Buckets, one for each team, is placed across the Centre Line. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a ball, rides to the Centre Line and places the ball in the bucket. They continue to the Changeover End, dismount, pick up a ball, remount and return to hand the ball to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way in succession, with Number Four placing the last ball in the bucket on the way back. When dismounted, the rider must hold the pony by the nearer rein throughout. The winning team is the one whose Number Four is first over the Start/Finish Line with five balls in the bucket. Line Stewards replace balls knocked out of the circle, if it is safe to do so. If a ball is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that ball must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            BallAndBucketDiagram),

        new Entry("Boule and Bucket", "Ball",
            "As Ball and Bucket, but with plastic boules instead of tennis balls.",
            "Four plastic boules for each team are placed within a marked circle 3 m behind the Changeover Line. A row of Buckets, one for each team, is placed across the Centre Line. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a boule, rides to the Centre Line and places the boule in the bucket. They continue to the Changeover End, dismount, pick up a boule, remount and return to hand it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way in succession, with Number Four placing the last boule in the bucket on the way back. When dismounted, the rider must hold the pony by the nearer rein throughout. The winning team is the one whose Number Four is first over the Start/Finish Line with five boules in the bucket. Line Stewards replace boules knocked out of the circle, if it is safe to do so. If a boule is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that boule must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            BouleAndBucketDiagram),

        new Entry("Tennis Ball Shuffle", "Ball",
            "Move a tennis ball between a socket on the centre line and two cones level with Poles 1 and 4.",
            "A pole topped with a socket containing a tennis ball, in the 9 o'clock position as viewed from the Start/Finish Line, is placed on the Centre Line. Ball Cones are placed level with Poles 1 and 4. Numbers One and Three are mounted at the Start/Finish End and Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One, carrying a tennis ball, rides to the cone level with Pole 1 and places the ball on it. They then ride to the socket, remove the ball, and place it on the cone level with Pole 4 before crossing the Changeover Line. Number Two collects the ball from the cone level with Pole 4 and places it in the socket, in any position. They then ride to the cone level with Pole 1, remove the ball and hand it to Number Three behind the Start/Finish Line. Number Three repeats the actions of Number One. Number Four repeats the actions of Number Two and carries the final tennis ball across the Start/Finish Line.",
            TennisBallShuffleDiagram),

        new Entry("Four Ball Cone (Tennis Ball Shuffle)", "Ball",
            "Collect a tennis ball from a penny dish at the Changeover and place on cones one by one.",
            "Four Ball Cones level with Poles 1–4; a pole topped with a Penny Dish containing four tennis balls 3 m beyond the Changeover. Each rider in turn collects a ball from the Penny Dish and places it on any cone on the way back. Winner: Number Four first over the line with a ball on every cone.",
            FourBallConeDiagram),

        new Entry("Four Ball Cone (2002)", "Ball",
            "Collect a tennis ball from a penny dish at the Changeover and place it on any ball cone, one rider at a time.",
            "Four Ball Cones in a line down the arena, level with Poles 1–4; a Bending Pole topped with a Penny Dish holding four tennis balls 3 m behind the Changeover Line, in line with the cones. All four riders start from the Start/Finish End. Number One rides across the Changeover Line, collects a ball from the Penny Dish, rides back and places it on any ball cone before crossing the Start/Finish Line. Numbers Two, Three and Four repeat. Winner: Number Four first over the Start/Finish Line with a tennis ball on each of the four ball cones.",
            FourBallConeDiagram),

        // ── Flag family ───────────────────────────────────────────────────
        new Entry("Two Flag", "Flag",
            "Move a single flag between two flag cones level with Poles 1 and 4.",
            "There are two Flag Cones for each team, placed level with Poles 1 and 4, with a flag in the Flag Cone level with Pole 4. Numbers One and Three are at the Start/Finish End and Numbers Two and Four are at the Changeover End. On the signal to start, Number One, carrying a flag, rides to the Flag Cone level with Pole 1 and places the flag in it. They then ride to the Flag Cone level with Pole 4, take out the flag and hand it to Number Two behind the Changeover Line. Number Two places the flag in the Flag Cone level with Pole 4, rides to the Flag Cone level with Pole 1, takes out the flag and hands it to Number Three behind the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two respectively. Flag Cones that are knocked over must be set up immediately by the rider concerned. If a flag comes off its cane, the cane alone may be used to complete the race. The winning team is the one whose Number Four is first over the Start/Finish Line carrying a flag.",
            TwoFlagDiagram),

        new Entry("Four Flag", "Flag",
            "Distribute four flags from a centre cone into two outer cones.",
            "There are three Flag Cones for each team: one level with Pole 1, one on the Centre Line and one level with Pole 5. Four flags are placed in the Flag Cone on the Centre Line. All four riders are mounted at the Start/Finish End. On the signal to start, Number One rides to the Flag Cone on the Centre Line, picks up a flag and places it in either the Flag Cone level with Pole 1 or the Flag Cone level with Pole 5, then crosses the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One, each collecting a flag from the Centre Line cone and placing it in one of the other two cones. The order in which flags go into the cones is not fixed by the rules. The winning team is the one whose Number Four is first over the Start/Finish Line with two flags in each of the Flag Cones level with Poles 1 and 5, leaving the Centre Line cone empty. Flag Cones that are knocked over must be set up immediately by the rider concerned. If a flag comes off its cane, the cane alone may be used. On windy days rubber bands may be used to keep the flags furled.",
            FourFlagDiagram),

        new Entry("Five Flag", "Flag",
            "Five flags are moved one at a time into a flag cone behind the Changeover Line, and Number Four finishes carrying the fifth.",
            "A Flag Cone is placed 3 m behind the Changeover Line and another on the Centre Line. Each team has five flags on canes: four are in the Flag Cone on the Centre Line and one is carried by Number One at the start. On the signal to start, Number One rides to the Changeover End and places the flag they are carrying in the Flag Cone, then rides back, takes a flag from the Flag Cone on the Centre Line and hands it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way, up and down the arena in succession, so that the team has placed four flags in the Flag Cone at the far end of the arena and Number Four finishes over the Start/Finish Line mounted and carrying the fifth flag. If a Flag Cone is knocked over, the rider must put it up again, replacing any flags that were in it. If a rider takes more than one flag from the Flag Cone, they must replace the surplus. They may dismount to correct mistakes. The winning team is the one whose Number Four is first over the Start/Finish Line carrying a flag. If a flag comes off its cane, the cane may be used to complete the race. On windy days rubber bands can be used to keep the flags furled.",
            FiveFlagDiagram),

        new Entry("Tubular Flag Race", "Flag",
            "Flags are placed one at a time into the tubes of a four-flag holder behind the Changeover Line, starting with the blue centre tube.",
            "A Four Flag Holder is placed 3 m behind the Changeover Line, and four white flags are placed in a Flag Cone on the Centre Line. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying the BLUE PG LOGO flag, rides to the Changeover End and places it, from the mounted position, in the matching blue tube in the centre of the Flag Holder. They ride back, pick up a white flag from the Flag Cone on the Centre Line and hand it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One, matching their white flags to any of the remaining tubes. Number Four, having placed their white flag in the Flag Holder, collects the final white flag from the Flag Cone on the Centre Line and rides over the Start/Finish Line. The winning team is the one whose Number Four crosses the Start/Finish Line carrying the flag. If a rider knocks over the Flag Holder, the other flags may be corrected from the ground, but the rider's own flag must always be placed from the mounted position. The Four Flag Holder has four plastic tubes, the central one blue and the other three white, equally spaced around it, set in a weighted conical base. At external shows and competitions, provided the first flag is a different colour from the others, goes in the centre tube and stays there, it need not be blue and the others need not be white; the Chief Steward should say which colours will be used before the competition starts.",
            TubularFlagDiagram),

        // ── Bottle family ─────────────────────────────────────────────────
        new Entry("Bottle", "Bottle",
            "A bottle on a table at the Changeover End is swapped with one carried by the team, using a second table on the Centre Line.",
            "There are two Tables for each team: one on the Centre Line and the other 3 m beyond the Changeover Line. On the table beyond the Changeover Line is a plastic 750 ml Bottle filled with sand or similar to weigh 500 g. On the signal to start, Number One, carrying a similar bottle, rides to the Table on the Centre Line, places the bottle upright on it, rides to the Changeover End, picks up the bottle from the Table there and returns to hand it to Number Two behind the Start/Finish Line. Number Two rides to the Table at the Changeover End, places the bottle upright on it, then rides back down the arena, collecting the bottle from the Table on the Centre Line on the way and handing it to Number Three behind the Start/Finish Line. Number Three repeats the actions of Number One, ending by handing the bottle to Number Four. Number Four repeats the actions of Number Two. The winning team is the one whose Number Four crosses the Start/Finish Line first, mounted and carrying the bottle. Any bottle or table that is knocked over must be replaced upright.",
            BottleDiagram),

        new Entry("Bottle Collection", "Bottle",
            "Four bottles are collected from a table at the Changeover End and placed in a bottle carrier on a table level with Pole 1.",
            "There are two Tables for each team: one in line with Pole 1 and the other in line with the first, 3 m beyond the Changeover Line. On the Table at the Changeover End are four plastic Bottles weighted with sand. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a plastic Bottle Carrier, rides to the Table level with Pole 1 and places the Carrier upright on it. Number One then rides to the Changeover End, picks up any of the bottles from the Table, returns to place it upright in the Carrier and rides across the Start/Finish Line. Numbers Two, Three and Four in turn ride to the Table at the Changeover End, collect any bottle, return to the Table at Pole 1 and place the bottle in the Carrier. Numbers Two and Three then ride across the Start/Finish Line. Number Four, after placing their bottle, picks up the Carrier and carries it across the Start/Finish Line. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the Bottle Carrier containing four bottles. Any bottle knocked over must be replaced upright. The Carrier must be carried by its handle when Number One places it on the Table and when Number Four picks it up and carries it across the line.",
            BottleCollectionDiagram),

        new Entry("Quoit and Bottle", "Bottle",
            "Place a bottle upright on a table, then ring it with four quoits collected from behind the Changeover Line.",
            "A Table is placed level with Pole 1. In line with the Table, four rubber Quoits are placed on the ground in a circle marked 3 m beyond the Changeover Line. All four riders are mounted at the Start/Finish End. Number One, carrying a Bottle (senior type, weighing 500 g), rides to the Table and places the bottle upright on it. They then ride to the Changeover End, dismount, collect a quoit, remount and, on the way back down the arena, place the quoit over the bottle on the Table before riding across the Start/Finish Line. Numbers Two, Three and Four in turn ride to the Changeover End, dismount, collect a quoit, remount and, on the way back, place the quoit over the bottle on the Table before crossing the Start/Finish Line. If the Table is knocked over, or a bottle is knocked over or off the Table, the rider must reset all the equipment before continuing. Line Stewards replace any quoits in the circle where possible if a pony knocks them out. The winning team is the one whose Number Four is first over the Start/Finish Line with the bottle standing upright and all four quoits correctly placed over it. The bottle must remain upright throughout the race, and quoits must be fully over the bottle and not hanging from it.",
            QuoitAndBottleDiagram),

        // ── Sack family ───────────────────────────────────────────────────
        new Entry("Big Sack", "Sack",
            "All four riders run together in one big sack down the arena.",
            "A Big Sack is placed 1 m beyond the Centre Line. Number Five stands behind the Changeover Line. Numbers One and Two form up on foot behind the Start/Finish Line, with Number One holding Number Two's pony on the nearside and Number Two standing beside them facing forward. Numbers Three and Four form up in the same way behind the Start/Finish Line, with Number Three holding Number Four's pony. On the signal to start, Numbers Two and Four mount their ponies; they must do this before crossing the Start/Finish Line. Numbers One and Three each lead the pony they are holding down the arena and across the Changeover Line, where Numbers Two and Four dismount and Numbers One and Three hand the ponies to Number Five. Ponies may be handed over before or after Numbers Two and Four dismount. Numbers One, Two, Three and Four then run back and step into the Big Sack. All four make their way in the sack down the arena and across the Start/Finish Line. The winning team is the one whose sack, containing all four members, is first over the Start/Finish Line. The white hat band can be worn by any rider who is in the sack when crossing the Start/Finish Line.",
            BigSackDiagram),

        new Entry("Small Sack", "Sack",
            "Each rider in turn dismounts, gets into a sack and runs or jumps down the arena leading their pony.",
            "Number One, carrying a sack, and Number Three are mounted behind the Start/Finish Line. Numbers Two and Four are mounted behind the Changeover Line. On the signal to start, Number One rides forward and, before crossing the Centre Line, dismounts and gets into the sack. Number One then runs or jumps down the arena, leading their pony, and hands the sack to Number Two behind the Changeover Line. Number Two rides forward and, before crossing the Centre Line, dismounts and gets into the sack, then runs or jumps down the arena, leading their pony, and hands the sack to Number Three. Numbers Three and Four repeat the actions of Numbers One and Two up and down the arena in succession. The winning team is the one whose Number Four is first over the Start/Finish Line on their feet in the sack. Getting out of the sack and handing it to the next rider must be done beyond the Changeover Line or the Start/Finish Line as appropriate. Riders must not get into the sack until they have dismounted, and the top of the sack must not be rolled down. Every effort should be made to hold the sack above knee level throughout. Riders must be on their feet when crossing the line, and ponies must be led by the nearer rein only.",
            SmallSackDiagram),

        new Entry("Three-Legged Sack", "Sack",
            "Pairs of riders run back together with one leg each in a sack, leading their ponies.",
            "Numbers One and Three are mounted at the Start/Finish End and Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One, carrying a sack, rides up the arena, over the Changeover Line, and dismounts. Number Two dismounts when Number One has crossed the Changeover Line. Numbers One and Two each put one leg into the sack. Holding the sack in one hand and leading their ponies with the other, they run back together over the Start/Finish Line. The sack is then handed to Number Three, who repeats the actions of Number One, and Number Four repeats the actions of Number Two. The winning team is the one whose Numbers Three and Four are first over the Start/Finish Line. The sack may be handed to the outgoing rider before the incoming rider has dismounted, provided the incoming pony's feet have fully crossed the line. Ponies must be led by the nearer rein until the rider has completed their part of the race.",
            SmallSackDiagram),

        // ── Dismount family ───────────────────────────────────────────────
        new Entry("Stepping Stones", "Dismount",
            "Each rider dismounts, leads their pony and steps on each of six stones straddling the Centre Line, then remounts.",
            "Six Stepping Stones are placed 30 cm apart, straddling the Centre Line, in a straight line up and down the arena between the lines of Bending Poles. Numbers One and Three are mounted at the Start/Finish End and Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One rides to the Stepping Stones, dismounts and, leading their pony, steps on each stone in turn and then onto the ground with the opposite foot from the one used to step on the final stone, before remounting and riding across the Changeover Line. Number Two does the same and rides across the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two respectively. If a pony or rider knocks over a Stepping Stone, or a rider steps on the ground while crossing the stones, they must set up any fallen stones and return to cross all the stones again from the direction they first attempted. When dismounted, riders must lead the pony by the nearer rein throughout. The winning team is the one whose Number Four is first across the Start/Finish Line.",
            SteppingStonesDiagram),

        new Entry("Hurdles", "Dismount",
            "In pairs, one rider hands over their pony and negotiates four hurdles by stepping over and crawling under.",
            "Four Hurdles are placed about 1.85 m apart in a straight line up and down the arena, straddling the Centre Line. Viewed from the Start/Finish Line they are alternately low and high, and an inverted mug is placed on each of the two higher hurdles. Numbers One and Two form up side by side behind the Start/Finish Line, with Number Four behind the 6 m line. Number Three stands behind the Changeover Line. All four are mounted. On the signal to start, Numbers One and Two ride towards the Hurdles. Number One dismounts and hands their pony to Number Two, then steps over the first Hurdle, crawls under the second, steps over the third and crawls under the fourth. Number One remounts and both riders ride across the Changeover Line, where Number One waits. Number Two turns round and Numbers Two and Three ride to the Hurdles, where Number Two dismounts and hands their pony to Number Three, then crawls under the first Hurdle, steps over the second, crawls under the third and steps over the fourth. Number Two remounts and both riders ride over the Start/Finish Line, where Number Two waits. Number Three turns round and Numbers Three and Four complete the course in the same way, with Number Three negotiating the Hurdles. Number Three then drops out and Numbers Four and One complete the course, with Number Four negotiating the Hurdles. The winning team is the one whose final pair is first across the Start/Finish Line mounted on their ponies. At each changeover, the next pony to go must stay behind the line until both of the previous riders have crossed it. The rider who is to hold the pony at the Hurdles may take hold of its rein before, or as they ride down the arena. The pony must be led by the rein nearer the ridden pony and not by the bit ring or any other part of the bridle. If a Hurdle is knocked over or a mug falls off, the rider concerned must replace it, return to the first Hurdle and negotiate all the Hurdles again. Mugs must be replaced inverted and should have coloured tape around the lip for ease of judging.",
            HurdlesDiagram),

        new Entry("Tyre", "Dismount",
            "In pairs, one rider hands over their pony, gets through a motorcycle tyre on the Centre Line and remounts.",
            "A motorcycle Tyre is placed on the Centre Line for each team. Numbers One and Two form up behind the Start/Finish Line, with Number Four behind the 6 m line. Number Three is behind the Changeover Line. On the signal to start, Numbers One and Two ride to the Tyre, where Number One dismounts, hands their pony to Number Two, gets through the Tyre and remounts. Both riders then continue across the Changeover Line, where Number One waits. Numbers Two and Three then ride to the Tyre, where Number Two dismounts, hands their pony to Number Three, gets through the Tyre and remounts. Both riders continue across the Start/Finish Line and Number Two leaves the race. Numbers Three and Four then ride to the Tyre, where Number Three dismounts, hands their pony to Number Four, gets through the Tyre and remounts. Both riders continue across the Changeover Line, Number Three drops out, and Number Four and Number One complete the race in a similar way, with Number Four going through the Tyre. The winning team is the one whose final pair (Numbers One and Four) cross the Start/Finish Line first, mounted on their ponies. At each changeover, the next pony to go must remain behind the line until both incoming riders have crossed it. The rider who is to lead the pony may take hold of the rein behind the line or as they go down the arena. The pony must be led by the rein nearer the ridden pony and not by the bit ring or any other part of the bridle. The Tyre may not be touched until the pony has been correctly handed over. Riders may not run with the Tyre. The Tyre must remain between Poles 2 and 3 and in the team's lane throughout the race. If it rolls or is dragged outside Poles 2 and 3 in their lane, the dismounted rider must retrieve it before resuming the race.",
            TyreDiagram),

        new Entry("Grooms", "Dismount",
            "Riders lead a teammate's pony through four bending poles, handing it over at each changeover.",
            "Four Bending Poles are placed in a line 7 to 9 m apart. Number One lines up behind the Start/Finish Line holding Number Two's pony. Number Three is behind the 6 m line holding Number Four's pony. Number Two is behind the Changeover Line, unmounted, holding Number Three's pony. Number Four stands behind Number Two beyond the Changeover Line. On the signal to start, Number One rides through the Bending Poles leading Number Two's pony. On crossing the Changeover Line, Number One hands Number Two's pony to Number Two. Number Two mounts and rides through the Bending Poles leading Number Three's pony, over the Start/Finish Line. Once Number Two has crossed the Changeover Line into the field of play, Number One dismounts and hands their own pony to Number Four. On crossing the Start/Finish Line, Number Two hands Number Three's pony to Number Three. Number Three mounts and rides through the Bending Poles leading Number Four's pony. On receiving their pony, Number Four mounts and rides through the Bending Poles leading Number One's pony to complete the race. If a rider lets go of a pony they are leading, they must regain possession and resume the race from the point where the fault occurred. Having completed the handover, an incoming rider may not re-cross into the field of play to give a lead or encouragement. Ponies must be led by the rein nearer the ridden pony; no other part of the bridle may be held at any time.",
            GroomsDiagram),

        // ── Equipment / Trays ─────────────────────────────────────────────
        new Entry("Equipment Jumble", "Equipment",
            "Build a stack of pyramid box, quoit, mug and tennis ball on a table at Pole 1.",
            "All four riders are mounted behind the Start/Finish Line. Four items, a Pyramid Box, a Quoit, a Mug and a Tennis Ball, are placed in a circle marked 3 m behind the Changeover Line. A Table is placed level with Pole 1, in line with the circle. On the signal to start, Number One rides towards the Changeover End, dismounts, picks up the Pyramid Box, remounts, rides to place the Pyramid Box on the Table and then rides across the Start/Finish Line. Number Two repeats the actions of Number One, collecting the Quoit and placing it on top of the Pyramid Box. Number Three repeats the actions of Number One, collecting the Mug and placing it, open end up, inside the Quoit on top of the Pyramid Box. Number Four repeats the actions of Number One, collecting the Tennis Ball and placing it inside the Mug before crossing the Start/Finish Line. All four items must remain on top of each other on the Table, with the Tennis Ball inside the Mug. The Pyramid Box may be on the edge of the Table, the Quoit may overhang the edge of the Pyramid Box, and the Mug may touch the Quoit at an angle. The winning team is the one whose Number Four is first over the Start/Finish Line, mounted, with all four items stacked correctly on the Table.",
            EquipmentJumbleDiagram),

        new Entry("Farmers' Market", "Equipment",
            "Fill a tack box tray on a table with milk, potato, sausages and an egg box, then carry the tray over the line.",
            "A Table is placed level with Pole 1. 3 m behind the Changeover Line, each team has four items, a string of sausages, a potato, an egg box and a bottle of milk, placed on the ground in a circle, with the bottle of milk upright. All four riders line up at the Start/Finish End. On the signal to start, Number One, carrying a Tack Box Tray, rides to the Table and places the tray on it. They ride to the Changeover End, dismount, pick up the bottle, remount, return to place the bottle in the tray and ride across the Start/Finish Line. Number Two rides towards the Changeover Line, dismounts, picks up the potato, remounts, returns to place it in the tray and crosses the Start/Finish Line. Number Three does the same, collecting the string of sausages. Number Four does the same, collecting the egg box, but having placed it in the tray, picks up the tray containing all four items and carries it across the Start/Finish Line. The bottle must be placed upright in the tray but need not stay upright once Number Four has collected the tray. The string of sausages may hang over the edge of the tray. The bottle of milk must remain upright while it is in the circle, and when it is placed in the tray, until Number Four collects the tray. Items other than the bottle that are knocked out of the circle should be replaced by the Line Steward concerned.",
            FarmersMarketDiagram),

        new Entry("Tack Shop", "Equipment",
            "Five-rider race: Number Five loads a grooming tray with one item for each rider, and the tray is kept on a table level with Pole 4.",
            "Race requires five members. A Bending Pole topped with a Penny Dish is erected level with Pole 1. A plastic Grooming Tray is placed on a Table level with Pole 4. Number Five stands behind a second Table placed 3 m behind the Changeover Line. On this Table are four items: a dandy brush, a tin of saddle soap or shoe polish, a tail bandage and a curry comb. Viewed from the Start/Finish Line they are placed tail bandage front right, dandy brush back right, rubber curry comb back left and tin of saddle soap or shoe polish front left. Number One carries a coin (10 cm diameter). On the signal to start, Number One rides to the Penny Dish and places the coin in it, continues to collect the Grooming Tray and rides with it to Number Five, who puts any one of the items in the tray. Number One then returns the tray to the Table level with Pole 4, rides to the Penny Dish, collects the coin and hands it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the race in the same way. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the coin, with all four items in the Grooming Tray on the Table level with Pole 4. If an item is dropped behind the Changeover Line, either the rider or Number Five may pick it up; it must be in the tray before the rider re-crosses the Changeover Line. Number Five may hold the pony's rein behind the Changeover Line. Number Five must remain behind the Table at the Changeover End. They may move to retrieve a piece of dropped equipment but must return to their position behind the Table before continuing their role in the race.",
            TackShopDiagram),

        new Entry("Bean Bag and Table", "Equipment",
            "Stack three bean bags and a tennis ball on a table level with Pole 1.",
            "Table level with Pole 1; three bean bags and a tennis ball placed randomly in a circle 3 m behind the Changeover. All four riders at Start/Finish. Numbers 1, 2 and 3 each ride up, dismount, collect a bean bag and place it on the table. Number Four collects the tennis ball and places it on the table. Bean bags and ball may touch. Winner: Number Four first over the line with all items on the table.",
            BeanBagAndTableDiagram),

        new Entry("Two Bean Bag Race (Junior)", "Equipment",
            "Junior version — swap two bean bags between a centre-line table and a table behind the Changeover.",
            "Two Tables per team: one on the Centre Line and one 3 m beyond the Changeover Line, with a bean bag on the Changeover table. All four riders line up mounted at the Start/Finish End. Number One, carrying a bean bag, places it on the Centre Line table, rides on to collect the bean bag from the Changeover table and returns to hand it to Number Two behind the Start/Finish Line. Number Two places the bean bag on the Changeover table, collects the one on the Centre Line table on the way back and hands it on. Number Three repeats Number One and Number Four repeats Number Two. Winner: Number Four first over the Start/Finish Line carrying a bean bag, with the other on the Changeover table.",
            TwoBeanBagJuniorDiagram),

        new Entry("Litter", "Equipment",
            "Spear pieces of litter with a cane and drop them in a bin on the centre line.",
            "Four identical pieces of litter for each team are placed side by side in a circle 3 m beyond the Changeover Line, with the open end facing the top of the arena so that riders can collect them on the turn or on the way back down the arena. A Litter Bin for each team is placed on the Centre Line. All four riders form up mounted behind the Start/Finish Line. On the signal to start, Number One, carrying a cane, rides to the Changeover End, picks up a piece of litter on the cane and returns to place it in the Litter Bin. Number One then rides back over the Start/Finish Line and hands the cane to Number Two. Numbers Two, Three and Four each repeat the actions of Number One. The winning team is the one whose Number Four is first over the Start/Finish Line, mounted and carrying the cane, with all four pieces of litter in the bin. Riders must remain mounted and must not hold the litter by hand when picking it up, carrying it on the cane or placing it in the bin. If a piece of litter becomes jammed on the cane, the rider may loosen it by hand before dropping it into the bin using the cane. A rider may pick up any piece of litter in the pile before re-crossing the Changeover Line, but after crossing it into the field of play they must continue with the same piece. Litter dropped when attempting to put it into the bin may be put in by hand, dismounted. Litter knocked out of the circle should be replaced by the Line Steward concerned. If a piece of litter is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that piece must pick it up and carry it over the Changeover Line before continuing the race.",
            LitterDiagram),

        new Entry("Old Sock", "Equipment",
            "Drop five socks into a bucket on the Centre Line, collecting a fresh sock from behind the Changeover Line each time.",
            "At the Changeover End each team has four socks sewn into balls about the size of a fist, placed on the ground in a circle 3 m beyond the Changeover Line. A row of buckets, one for each team, is placed across the Centre Line. All four riders form up behind the Start/Finish Line. On the signal to start, Number One, carrying a sock, rides to their team's bucket and drops the sock into it. They ride towards the Changeover Line, dismount, pick up a sock, remount and return over the Start/Finish Line to hand it to Number Two. Numbers Two, Three and Four complete the race in the same way in succession, with Number Four dropping the last sock into the bucket on the way back. The winning team is the one whose Number Four is first over the Start/Finish Line with five socks in their bucket. Socks knocked out of the circle should be replaced by the Line Steward concerned. If a sock is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that sock must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            OldSockDiagram),

        new Entry("Balloon and Cone", "Equipment",
            "Burst balloons on a board across the Centre Line with a pin-tipped cane; each rider must burst at least one.",
            "Six balloons are attached about 46 cm apart to a board placed in a straight line up and down the arena across the Centre Line. Numbers One and Three are behind the Start/Finish Line and Numbers Two and Four are behind the Changeover Line. Number One carries a cane about 1.22 m long with a pin fixed at one end. On the signal to start, Number One rides down the arena to the Changeover Line, bursting a balloon on the way, and hands the cane to Number Two behind the Changeover Line. Number Two rides down the arena to the Start/Finish Line, bursting a balloon on the way, and hands the cane to Number Three behind the Start/Finish Line. Numbers Three and Four complete the race in a similar way to Numbers One and Two. The winning team is the one whose Number Four is first over the Start/Finish Line, mounted and carrying the cane, with at least four of the balloons burst. Riders may make more than one attempt to burst a balloon, using either the point or the flat of the cane. There is no penalty if a rider bursts more than one balloon. However, each rider must burst at least one balloon, and if a rider fails to burst a balloon the team is eliminated.",
            BalloonAndConeDiagram),

        new Entry("Knickerbocker Glory Race", "Equipment",
            "Carry a plastic ball in an ice-cream cone up and back through five bending poles and hand the cone on.",
            "A line of five Bending Poles is set up 7 to 9 m apart in each lane, and each team has an Ice Cream Cone and a plastic ball about 15 cm in diameter. All four riders line up at the Start/Finish End. On the signal to start, Number One, holding the cone in their hand with the ball balanced in the cup, rides up and back, bending in both directions through the Bending Poles, and hands the cone with the ball on it to the next rider behind the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One in turn. The winning team is the one whose Number Four is first across the Start/Finish Line carrying the cone with the ball on it. If the ball is dropped or a pole is missed, the rider must retrieve the ball and replace it on the cone, or return to the point where the pole was missed, and then correct the mistake. The ball must not be touched by hand except when remounting. If the ball bounces back into the field of play during a handover, the incoming rider may retrieve it and hand it to the next rider without remounting. If the ball falls before the incoming rider has crossed the Start/Finish Line, they must collect the ball and remount before handing over the cone to the next rider.",
            KnickerbockerGloryDiagram),

        new Entry("Recycling Race", "Equipment",
            "Collect four items of recycling and put each through the correct slot of a wheelie bin level with Pole 1, then close the lid.",
            "A 120-litre Wheelie Bin with an insert with two slots, one circular and one rectangular, is placed in line with Pole 1 between two lines 50 cm apart. At the start of the race the lid is closed, with the handles facing the Changeover End. 3 m behind the Changeover Line, placed on the ground in a circle in any position, are four items of recycling: a bottle, a tin can, a newspaper and a letter. All four riders are mounted at the Start/Finish End. On the signal to start, Number One rides up the arena to the Wheelie Bin and opens the lid, then rides to the Changeover End, dismounts, collects any item of recycling, remounts and returns to the bin, where they put the item in through the correct slot: the bottle and tin can through the circular hole, the newspaper and letter through the rectangular slot. Number One then crosses the Start/Finish Line. Numbers Two and Three repeat the actions of Number One. Number Four rides to the Changeover End, dismounts, collects the last item of recycling, remounts, returns to the bin and puts the item in through the correct slot. After placing the final item, Number Four closes the lid before crossing the Start/Finish Line to end the race. Once opened by Number One, the lid must stay open until Number Four closes it after placing their final item. If the bin is knocked over or accidentally moved during the race, the rider responsible must replace it upright between the two lines, with the handles facing the Changeover End and the wheels not touching either line. Any items that have fallen out must be put back in the bin, and the insert must be put back in the correct position so that the lid can be closed fully. If the insert is incorrectly replaced during the race and not corrected by the rider concerned, the team is eliminated. Other riders may not correct an insert displaced by another rider. If the bin is knocked but does not fall over and is at a different angle (provided it is not touching either line), the rider may continue without moving it back to its original angle. Line Stewards replace any items in the circle where it is safe to do so.",
            RecyclingDiagram),

        // ── Letter-pole family ────────────────────────────────────────────
        new Entry("PGSPORTS Pole", "Letter Pole",
            "Slot eight lettered cartons onto a pole so they read PGSPORTS from top to bottom.",
            "3 m beyond the Changeover Line, seven one-litre washing-up liquid cartons are placed randomly in a circle marked on the ground, lettered P, G, S, P, O, R and T. A Bending Pole is erected level with Pole 1. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a carton marked 'S', rides to the pole and slots the carton over it. Number One then continues to the Changeover End, dismounts, collects the carton marked 'T', remounts and returns to slot it over the pole. Number One then returns to the Changeover End, dismounts, collects the carton marked 'R', remounts and rides down the arena to hand it to Number Two behind the Start/Finish Line. Numbers Two and Three repeat these actions in turn, Number Two collecting the cartons marked 'O' and 'P' and Number Three the cartons marked 'S' and 'G', in each case either slotting them over the pole or handing them to the next rider. Number Four slots the carton marked 'G' on the pole, continues to the Changeover End, dismounts and collects the carton marked 'P', then rides down the arena and across the Start/Finish Line, slotting the 'P' on the pole on the way. The winning team is the one whose Number Four is first over the Start/Finish Line with all eight cartons on the pole, reading 'PGSPORTS' from the top to the bottom of the pole. Cartons placed in the wrong order, or the wrong way up, must be corrected by the rider concerned. Cartons knocked out of the circle should be replaced by the Line Steward concerned. If a carton is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that carton must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            LetterPole8Diagram),

        new Entry("Pony Club Pole", "Letter Pole",
            "Slot eight lettered cartons onto a pole so they read PONY CLUB from top to bottom.",
            "As PGSPORTS Pole, with these differences. The seven cartons in the circle 3 m beyond the Changeover Line are lettered P, O, N, Y, C, L and U, and Number One carries the carton marked 'B'. Number One slots the 'B', then collects 'U' and slots it, then collects 'L' and hands it to Number Two. Number Two collects 'C' and then 'Y'. Number Three collects 'N' and then 'O'. Number Four slots the 'O' on the pole, continues to the Changeover End, dismounts and collects 'P', then rides across the Start/Finish Line, slotting the 'P' on the pole on the way. In each case the rider either slots the carton over the pole or hands it to the next rider. The winning team is the one whose Number Four is first over the Start/Finish Line with all eight cartons on the pole, reading 'PONY CLUB' from the top to the bottom of the pole. Cartons placed in the wrong order, or the wrong way up, must be corrected by the rider concerned. Cartons knocked out of the circle should be replaced by the Line Steward concerned. If a carton is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that carton must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            LetterPole8Diagram),

        new Entry("Spillers Pole", "Letter Pole",
            "Slot eight lettered cartons onto a pole so they read SPILLERS from top to bottom.",
            "As PGSPORTS Pole, with these differences. The seven cartons in the circle 3 m beyond the Changeover Line are lettered S, P, I, L, L, E and R, and Number One carries the carton marked 'S'. Number One slots the 'S', then collects 'R' and slots it, then collects 'E' and hands it to Number Two. Number Two collects the two cartons marked 'L', in either order. Number Three collects 'I' and then 'P'. Number Four slots the 'P' on the pole, continues to the Changeover End, dismounts and collects 'S', then rides across the Start/Finish Line, slotting the 'S' on the pole on the way. In each case the rider either slots the carton over the pole or hands it to the next rider. The winning team is the one whose Number Four is first over the Start/Finish Line with all eight cartons on the pole, reading 'SPILLERS' from the top to the bottom of the pole. Cartons placed in the wrong order, or the wrong way up, must be corrected by the rider concerned. Cartons knocked out of the circle should be replaced by the Line Steward concerned. If a carton is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that carton must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            LetterPole8Diagram),

        new Entry("Robinsons Pole", "Letter Pole",
            "Slot nine lettered cartons onto a pole so they read ROBINSONS from top to bottom.",
            "As PGSPORTS Pole, with these differences. Eight cartons are placed randomly in the circle 3 m beyond the Changeover Line, lettered R, O, B, I, N, S, O and N, and Number One carries the carton marked 'S'. Number One slots the 'S', then collects either carton marked 'N' and slots it, then collects either carton marked 'O' and hands it to Number Two. Number Two collects 'S' and then 'N'. Number Three collects 'I' and then 'B'. Number Four slots the 'B' on the pole, continues to the Changeover End, dismounts, collects the remaining 'O', remounts and returns to slot it over the pole, then rides back to the Changeover End, dismounts, collects the 'R', remounts and rides across the Start/Finish Line, slotting the 'R' on the pole on the way. In each case the rider either slots the carton over the pole or hands it to the next rider. The winning team is the one whose Number Four is first over the Start/Finish Line with all nine cartons on the pole, reading 'ROBINSONS' from the top to the bottom of the pole. Cartons placed in the wrong order, or the wrong way up, must be corrected by the rider concerned. Cartons knocked out of the circle should be replaced by the Line Steward concerned. If a carton is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that carton must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            LetterPole9Diagram),

        new Entry("STRUK Pole", "Letter Pole",
            "Slot lettered and blank cartons onto a pole so they read S, T, R, U, K and three blanks from top to bottom.",
            "A Bending Pole is set up level with Pole 1, in line with a circle at the Changeover End. In the circle on the ground 3 m beyond the Changeover Line, seven cartons are placed randomly, lettered S, T, R, U, K and two blanks. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a blank carton, rides to the pole and slots it over the pole. They continue to the Changeover End, dismount, collect a blank carton, remount, ride down the arena and slot it over the pole, then ride back to the Changeover End, dismount, collect the other blank carton, remount, ride down the arena and hand it to Number Two behind the Start/Finish Line. Number Two slots the blank carton over the pole, continues to the Changeover End and collects the carton marked K, slots it, then collects the carton marked U and hands it to Number Three. Number Three slots the U, collects R and slots it, then collects T and hands it to Number Four. Number Four slots the T, continues to the Changeover End, collects S, and slots it on the way across the Start/Finish Line. Each carton is collected dismounted and the rider remounts before riding back. The winning team is the one whose Number Four is first over the Start/Finish Line with all eight cartons on the pole, reading from top to bottom S, T, R, U, K, blank, blank, blank. Cartons placed in the wrong order, or the wrong way up, must be corrected by the rider concerned; the narrow neck of each carton is the top. Cartons kicked out of the circle by a pony should be replaced by the Line Steward concerned. If a carton is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that carton must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            LetterPole8Diagram),

        // ── Spelling family ───────────────────────────────────────────────
        new Entry("Spell E G U K", "Spelling",
            "Hang eight cards from the Centre Line table on a gibbet, with EGUK on the top row and four logos on the bottom row.",
            "A Table is placed on the Centre Line with eight cards (20 cm square) on it, placed randomly in pairs. Four of the cards have the letters E, G, U and K on one side and K, U, G and E on the other; the other four have an EGUK logo on each side. Number Five stands 3 m behind the Changeover Line holding a Gibbet, which has two crossbars each with four hooks screwed to the lower edge. On the signal to start, Number One rides to the Table, picks up any two cards, rides to the Gibbet and hangs them on the correct hooks so that, viewed from the Start/Finish Line, the top row of hooks spells EGUK and the bottom row of hooks shows four EGUK logos. Number One then rides down the arena and across the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One. The winning team is the one whose Number Four is first back across the Start/Finish Line with all eight cards on the hooks, EGUK on the top row and four logos on the bottom row. Number Five must hold the Gibbet upright. They may not help physically but can speak to any of the riders. Dropped letters may be retrieved dismounted but must always be hung from the mounted position.",
            Spell8CardsDiagram),

        new Entry("Spell EQUI TREK", "Spelling",
            "Hang eight lettered cards on a gibbet, with EQUI on the top row and TREK on the bottom row.",
            "A Table is placed on the Centre Line with eight cards (20 cm square) on it, placed randomly in pairs. The cards are marked with the letters spelling EQUI TREK. Number Five stands 3 m behind the Changeover Line holding a Gibbet, which has two crossbars each with four hooks screwed to the lower edge. On the signal to start, Number One rides to the Table, picks up any two cards, rides to the Gibbet and hangs them on the correct hooks so that, viewed from the Start/Finish Line, the top row of hooks spells EQUI and the bottom row of hooks spells TREK. Number One then rides down the arena and across the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One. The winning team is the one whose Number Four is first back across the Start/Finish Line with all eight cards on the hooks, EQUI on the top row and TREK on the bottom row. Number Five must hold the Gibbet upright. They may not help physically but can speak to any of the riders. Dropped letters may be retrieved dismounted but must always be hung from the mounted position.",
            Spell8CardsDiagram),

        new Entry("Spell PONY CLUB", "Spelling",
            "Hang eight lettered cards on a gibbet, with PONY on the top row and CLUB on the bottom row.",
            "A Table is placed on the Centre Line with eight cards (20 cm square) on it, placed randomly in pairs. The cards are marked with the letters spelling PONY CLUB. Number Five stands 3 m behind the Changeover Line holding a Gibbet, which has two crossbars each with four hooks screwed to the lower edge. On the signal to start, Number One rides to the Table, picks up any two cards, rides to the Gibbet and hangs them on the correct hooks so that, viewed from the Start/Finish Line, the top row of hooks spells PONY and the bottom row of hooks spells CLUB. Number One then rides down the arena and across the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One. The winning team is the one whose Number Four is first back across the Start/Finish Line with all eight cards on the hooks, PONY on the top row and CLUB on the bottom row. Number Five must hold the Gibbet upright. They may not help physically but can speak to any of the riders. Dropped letters may be retrieved dismounted but must always be hung from the mounted position.",
            Spell8CardsDiagram),

        new Entry("Spell PONY PREP", "Spelling",
            "Hang eight lettered cards on a gibbet, with PONY on the top row and PREP on the bottom row.",
            "A Table is placed on the Centre Line with eight cards (20 cm square) on it, placed randomly in pairs. The cards are marked with the letters spelling PONY PREP. Number Five stands 3 m behind the Changeover Line holding a Gibbet, which has two crossbars each with four hooks screwed to the lower edge. On the signal to start, Number One rides to the Table, picks up any two cards, rides to the Gibbet and hangs them on the correct hooks so that, viewed from the Start/Finish Line, the top row of hooks spells PONY and the bottom row of hooks spells PREP. Number One then rides down the arena and across the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One. The winning team is the one whose Number Four is first back across the Start/Finish Line with all eight cards on the hooks, PONY on the top row and PREP on the bottom row. Number Five must hold the Gibbet upright. They may not help physically but can speak to any of the riders. Dropped letters may be retrieved dismounted but must always be hung from the mounted position.",
            Spell8CardsDiagram),

        new Entry("Spell PONY (Juniors)", "Spelling",
            "Junior version — pick up four letter cards from the centre line and hang them on a post to spell PONY.",
            "A Table on the Centre Line with four 20 cm square cards spelling PONY, placed side by side and separately spaced. Number Five stands 3 m behind the Changeover Line holding a post about 1.22 m (4 ft) high with a cross bar of four hooks facing Number Five. All four riders line up at the Start/Finish End. Number One picks up any one card, hands it to Number Five over the Changeover Line and waits behind the line until Number Five has hung it so that, viewed from the Start/Finish Line, the cards read PONY; Number One then returns across the Start/Finish Line. Numbers Two, Three and Four repeat. Number Five must stay behind the Changeover Line. A dropped card may be retrieved mounted or dismounted but must be handed to Number Five from the mounted position. Cards knocked off the Table can be replaced in any order. Winner: Number Four first over the Start/Finish Line with all four cards on the hooks spelling PONY.",
            Spell4CardsJuniorDiagram),

        // ── Sharpshooters / Bowling ───────────────────────────────────────
        new Entry("Sharpshooters (Version 1, with Target)", "Other",
            "Throw tennis balls from behind the Changeover Line to knock down two targets, one for each pair of riders.",
            "Two Bending Poles are placed 1 m apart, 3 m beyond the Changeover Line. A sleeved circular Target is slotted on top of each pole. A Bucket containing 12 tennis balls is placed on the Changeover Line. Numbers One and Two form up on foot behind the Start/Finish Line with one pony; Number One holds the pony, on either side, and Number Two stands on the other side. Both face forward. On the signal to start, Number Two mounts the pony, which must be done before crossing the Start/Finish Line. Number One then leads the pony down the arena and across the Centre Line and waits, holding it. After crossing the Centre Line, Number Two dismounts and runs to the Bucket. From behind the Changeover Line, Number Two throws tennis balls at either Target until it falls over. Number Two then runs back and takes hold of the pony, and Number One mounts; this must be done before crossing the Centre Line. Number Two then leads the pony back down the arena and over the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two respectively. The winning team is the one whose Number Three (mounted) and Number Four (leading the pony) are first across the Start/Finish Line with both Targets knocked down. If a team runs out of tennis balls, the rider concerned must run forward with the Bucket, collect any number of balls and then continue from behind the Changeover Line. Ponies must be led by the nearer rein throughout. The hat band must be on Number Three, who is mounted on the pony when crossing the Start/Finish Line. When throwing, the rider's foot must not touch the Changeover Line. Line Stewards move forward and level with the Changeover Line and call 'Fault, throw again' if a rider's foot touches the line while throwing. If a rider knocks down a Target with their foot on the line, it does not count and they must run to the Target and re-erect it before throwing again.",
            SharpshootersTargetDiagram),

        new Entry("Sharp Shooters (Version 2, with Net)", "Other",
            "Throw tennis balls from behind the Changeover Line into a net, one ball for each pair of riders.",
            "A Bending Pole is placed 3 m beyond the Changeover Line. On top of the pole is a vertically fixed Net, about 30 cm in diameter and deep enough to hold two tennis balls. A Bucket containing 12 tennis balls is placed in front of the Changeover Line. All four riders are unmounted at the Start/Finish End, with two ponies. Numbers One and Two form up on foot behind the Start/Finish Line with one pony; Number One may hold the pony on either side and Number Two stands on the opposite side, both facing forward. On the signal to start, Number Two mounts the pony, which must be done before crossing the Start/Finish Line. Number One then leads the pony down the arena and across the Centre Line and waits, holding it. After crossing the Centre Line, Number Two dismounts and runs to the Bucket. From behind the Changeover Line, Number Two throws tennis balls until one falls into the Net and stays there. Number Two then runs back and takes hold of the pony, and Number One mounts; this must be done before re-crossing the Centre Line. Number Two leads the pony back down the arena and over the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two respectively. If a team runs out of tennis balls, the rider concerned must run forward with the Bucket, collect any number of balls and then continue from behind the Changeover Line. The winning team is the one whose Numbers Three and Four are first over the Start/Finish Line, with Number Three mounted and Number Four leading the pony, and two tennis balls in the Net. Ponies must be led by the nearer rein throughout. The hat band must be on Number Three, who is mounted on the pony when crossing the Start/Finish Line. When throwing, the rider's foot must not touch the Changeover Line. Line Stewards move forward and level with the Changeover Line and call 'Fault, throw again' if a rider's foot touches the line while throwing. If a rider throws a ball into the Net with their foot on the line, it does not count and they must throw again.",
            SharpshootersNetDiagram),

        new Entry("Bowling", "Other",
            "Roll boules from behind the Changeover Line to knock down four bottles, one at a time, with pairs sharing a pony.",
            "Four full-sized bottles weighted with 500 g of sand are placed 30 cm apart, 3 m beyond the Changeover Line. A Bucket containing 12 weighted plastic boules is placed in front of the Changeover Line. All four riders are unmounted at the Start/Finish End, with two ponies. Numbers One and Two form up on foot behind the Start/Finish Line with one pony, each facing forward and on the same side. On the signal to start, Number One mounts the pony before crossing the Start/Finish Line. Number Two then leads the pony across the Centre Line and waits, holding it. Number One dismounts after the Centre Line, runs to the Bucket and, from behind the Changeover Line, bowls or throws a boule at the bottles. They must knock down only one bottle; if they knock down more, Number One must reset the others upright. Number One then runs to the pony and holds it while Number Two runs to the Bucket and bowls or throws a boule from behind the Changeover Line to knock down another bottle, resetting any extras. They then run back to the pony, Number Two mounts, and Number One leads and runs with the pony before crossing the Centre Line. The riders then ride and run back over the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two. The winning team is the one whose Number Four (riding) and Number Three (running) are first over the Finish Line. If a team runs out of boules, the rider concerned must run forward with the Bucket, collect any number and then continue from behind the Changeover Line as before. Ponies must be led by the nearer rein throughout. The white hat band is worn by Number Four, who is on the pony when crossing the Finish Line. When bowling or throwing, the rider's foot must not touch the line. Line Stewards move forward and level with the Changeover Line and call 'Fault, throw again' if the rider's foot touches the line.",
            BowlingDiagram),

        // ── Hi Lo / Rope ──────────────────────────────────────────────────
        new Entry("HI LO – Cone Specific", "Ball",
            "Put balls in a high net behind the Changeover Line, collecting from the cones in reverse order: Cone 4, then 3, 2 and 1.",
            "A line of four Ball Cones for each team is placed 7 to 9 m apart, level with Poles 1, 2, 3 and 4, with a tennis ball on top of each cone. Cone 1 is the nearest to the Start/Finish Line and Cone 4 the nearest to the Changeover Line. A pole 2.13 m high, topped with a Net, is set up 3 m behind the Changeover Line, in line with the row of cones. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a tennis ball, rides over the Changeover Line and places the ball in the Net, then rides back down the arena, collecting the ball from the top of Cone 4 on the way, and hands it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One, Number Two collecting the ball from Cone 3, Number Three from Cone 2 and Number Four from Cone 1. If a ball misses the Net and falls to the ground, the rider may dismount to pick it up, but must then remount and put the ball in the Net from the mounted position. When putting the ball in the Net, the rider may pass round the post or go directly in front of it. If a ball falls to the ground when being collected from a cone, or if any cone is knocked over, the rider must correct the error. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the last tennis ball.",
            HiLoDiagram),

        new Entry("Rope", "Other",
            "Pairs of riders weave through four bending poles holding a rope between them, changing partners at each line.",
            "Lines of four Bending Poles are erected about 7 to 9 m apart. Numbers One and Three are mounted at the Start/Finish End and Numbers Two and Four at the Changeover End. Number One carries a rope about 90 cm long. The rope must not be looped or knotted at any time, and holding hands during the race is not permitted. On the signal to start, Number One rides up, weaving through the Bending Poles, to cross the Changeover Line, where Number Two grasps the rope and both riders return through the Bending Poles holding the rope to the Start/Finish Line. After crossing the Start/Finish Line, Number One releases the rope and Number Three grasps it. Numbers Two and Three, each holding the rope, then ride up through the Bending Poles to cross the Changeover Line, where Number Two releases the rope and Number Four grasps it. Numbers Three and Four then ride back through the Bending Poles and over the Start/Finish Line, each holding the rope. The winning team is the one whose Numbers Three and Four cross the Start/Finish Line first, mounted and carrying the rope between them. Each time the rope is released and passed to another rider, all the ponies' legs must be over the Start/Finish Line or Changeover Line as appropriate. If either rider lets go of the rope, they must go back and resume the race from the point where the fault occurred.",
            RopeDiagram),

        // ── Specialty ─────────────────────────────────────────────────────
        new Entry("Sword", "Other",
            "Collect a ring from the top of a pole on a sword at each leg until the sword carries four rings.",
            "A line of four Bending Poles is erected about 7 to 9 m apart for each team. A plastic Sword ring with a 100 mm diameter hole is placed on each of the four poles, secured with an elastic band. On Poles 1 and 2 the stem of the ring is on the back edge of the pole; on Poles 3 and 4 it is on the front edge. Numbers One and Three are mounted behind the Start/Finish Line and Numbers Two and Four are mounted behind the Changeover Line. On the signal to start, Number One, holding a Sword, rides up the arena, collects a ring from the top of any pole using the Sword, rides over the Changeover Line and passes the Sword, with the ring still on it, to Number Two. Number Two rides down the arena, collects a ring from the top of any pole using the Sword, rides over the Start/Finish Line and passes the Sword, with the rings still on it, to Number Three. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four crosses the Start/Finish Line first holding the Sword with all four rings on it. The Sword must always be held behind the cross bar, with no part of the hand or fingers in front of it, throughout the race. If a ring is knocked off a pole or dropped, the rider may dismount and pick it up by hand. They may hold any rings already on the Sword with their fingers to help collect another, and must go back to where the error took place and continue holding the Sword behind the cross bar. To help with remounting, the rider may place the Sword against a pole and pick it up once mounted, but must again go back to where the error took place and continue holding the Sword behind the cross bar. If the Sword or rings are dropped during a handover, and a genuine attempt to hand over was made, the incoming rider may dismount, collect them and, still dismounted, hand the Sword to the outgoing rider, provided they hand it over with their hand behind the cross bar. If the Sword or rings are dropped over the Changeover Line and no genuine attempt to hand over was made, the incoming rider may dismount and pick them up but must remount before handing the Sword to the outgoing rider, with their hand behind the cross bar. If the outgoing rider drops rings into the field of play during a changeover, they must correct the error and re-cross the Changeover Line before continuing. There is no penalty if a pole is knocked down.",
            SwordDiagram),

        new Entry("Postman's", "Other",
            "Five-rider race: Number Five hands out four letters, which are carried back through the poles in a post bag.",
            "Four Bending Poles are placed in a line 7 to 9 m apart for each team. Number Five stands 3 m behind the Changeover Line, dismounted, holding four letters. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a Post Bag, rides through the Bending Poles and across the Changeover Line, where Number Five hands them a letter. Number One puts the letter in the Post Bag before re-crossing the Changeover Line, then returns through the Bending Poles to hand the Post Bag to Number Two behind the Start/Finish Line. Numbers Two, Three and Four each collect a letter from Number Five in the same way. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the Post Bag containing four letters. After receiving the letter from Number Five, the letter must be in the Post Bag and the rider's hand out of the bag before the rider crosses back into the field of play. Number Five must remain behind the Changeover Line throughout but, if necessary, may hold the pony while the rider puts the letter in the Post Bag. At the start of the race the top of the Post Bag must not be rolled down.",
            PostmansDiagram),

        new Entry("Post Box", "Other",
            "Five-rider race: post four newspapers through a post box on the Centre Line, carrying a coin between the riders.",
            "Race requires five members. A Bending Pole topped with a Penny Dish is set up level with Pole 1. A Post Box is placed on the Centre Line with its feet astride the Centre Line. Number Five stands in the circle 3 m behind the Changeover Line with four newspapers. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a coin (10 cm in diameter), rides to the Penny Dish and places the coin in it. They then ride across the Changeover Line, collect a newspaper from Number Five, ride back to the Post Box and post the newspaper through so that it drops on the ground on the Start/Finish side of the box. This must be done by pushing the newspaper through from the side of the Post Box nearer the Changeover Line, not by pulling it from the other side. They then ride to the Penny Dish, collect the coin and hand it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the race in the same way. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the coin. If the Post Box is knocked over, the rider concerned must replace it. If it is knocked from its original position, the rider may continue provided its feet are still astride the Centre Line, or at least one foot is touching the Centre Line. The newspaper must not be folded at any time during the race. The rider must make a genuine attempt to post the newspaper while mounted, but provided they have done so, if they drop it they may dismount and post it unmounted. At Zone and Championships the Post Box is 122 cm high (slot at 94 cm), 41 cm wide, with a slot opening of 3 cm by 25 cm, and the newspaper is a standard A4 (when flat) medical journal in a thin plastic sleeve or wallet.",
            PostBoxDiagram),

        new Entry("Pyramid – PGUK Version", "Equipment",
            "Stack four lettered boxes on the Centre Line table so they spell P G U K from the top.",
            "A Table is placed on the Centre Line and another 3 m behind the Changeover Line. On the second Table are four unstacked plastic boxes, each weighing 500 g, with a printed letter on each side. Viewed from the Start/Finish Line they are placed K front right, U back right, G back left and P front left. On the signal to start, Number One rides to the Table behind the Changeover Line, collects the box marked K and rides to place it on the Table on the Centre Line. Number One then returns across the Start/Finish Line. Number Two rides to the Table behind the Changeover Line, collects the box marked U and stacks it on the previous box on the Centre Line Table, then returns across the Start/Finish Line. Number Three (collecting G) and Number Four (collecting P) complete the race in the same way. The winning team is the one whose Number Four is first over the Start/Finish Line with all four boxes stacked on the Centre Line Table, spelling P G U K from the top. After collecting a box, the rider may adjust the stack by hand or with the box, before or after placing their box on the stack. If a Table is knocked over or a box falls, the rider concerned may dismount to replace them. At the Changeover End the boxes may be replaced in any order but must be placed side by side, not on top of each other. At the Centre Line Table the boxes must be stacked upright and in the correct order. Line Stewards will only signal once an incorrect box has been placed on the Centre Line Table.",
            PyramidDiagram),

        new Entry("PG Sports Shopping Spree Race", "Other",
            "Swap pennies from the Penny Dish for shopping bags, which are hung on hooks under the dish.",
            "A Bending Pole topped with a Penny Dish fitted with four hooks on the underside is erected on the Centre Line. The Penny Dish contains four pennies stacked on top of each other. In line with the Bending Pole, a Table is placed 3 m behind the Changeover Line, with a bucket on it holding four evenly spaced, branded canvas shopping bags. Each bag contains a Junior Bottle, which forms part of the equipment. Number Five stands behind the Table. All four riders are at the Start/Finish End. On the signal to start, Number One rides to the Centre Line, collects a penny from the Penny Dish, rides over the Changeover Line and hands the penny to Number Five. Number Five places the penny in the bucket and hands one of the shopping bags to Number One (the bag may be taken out of the bucket before the penny goes in). Number One then rides back to the Penny Dish and hangs the bag on any of the hooks on the underside of the dish, then rides back across the Start/Finish Line. Both handles of the bag must be hung on the same hook. Numbers Two, Three and Four repeat the actions of Number One, each using a separate hook for their bag. If, after a rider has crossed the Start/Finish Line, a handle becomes unhooked, the rider who is in the field of play at the time may replace the handle on the hook and continue the race. The winning team is the one whose Number Four is first over the Start/Finish Line with four pennies in the bucket and four branded shopping bags hanging correctly on the hooks under the Penny Dish.",
            ShoppingSpreeDiagram),

        new Entry("Quoits and Cone", "Equipment",
            "Ring a cone level with Pole 1 with four quoits collected from behind the Changeover Line, then top it with a tennis ball.",
            "A Ball Cone is placed level with Pole 1, in line with a circle marked on the ground beyond the Changeover Line. In the circle are placed three rubber Quoits and a Tennis Ball. All four riders are mounted at the Start/Finish End. Number One, carrying a quoit, rides to the cone and places the quoit over it, then rides on to the Changeover Line, dismounts, collects another quoit, remounts, returns across the Start/Finish Line and hands the quoit to the next rider behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way in succession, except that Number Four, instead of collecting a quoit, collects the tennis ball and places it on top of the cone on the way back to the Start/Finish Line. The winning team is the one whose Number Four is first over the Start/Finish Line with four quoits and a tennis ball on the cone. If the cone is knocked over, the rider must reset all the equipment before continuing. When dismounted, the rider must hold the pony by the nearer rein throughout. Line Stewards replace any quoits or the tennis ball in the circle where possible if a pony knocks them out. Quoits must be fully over the cone and the tennis ball correctly placed on the top.",
            QuoitsAndConeDiagram),

        new Entry("Fishing Race", "Other",
            "Five-rider race: hook plastic fish from a bin with a cane and hand them to Number Five to hang on a gibbet.",
            "A Bin containing four fish is placed on the Centre Line. Number Five stands 3 m behind the Changeover Line facing down the arena, holding a Gibbet with the hooks facing down the arena, away from Number Five. All four riders form up at the Start/Finish End. Number One has a cane with a small hook on one end. On the signal to start, Number One rides to the Bin, hooks a fish and continues over the Changeover Line to Number Five. Number Five unhooks the fish and secures it on any of the hooks on the Gibbet. Number One must remain behind the Changeover Line until Number Five has correctly placed the fish on the hook, then rides down the arena and hands the cane to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the race in the same way. The winning team is the one whose Number Four is first across the Start/Finish Line with all four fish on the Gibbet. If a rider drops a fish, they may pick it up, mounted or dismounted, before replacing it on the hook of the cane. If a fish is dropped while handing over to Number Five, Number Five may pick it up and put it on the Gibbet. The fish should be on the hook of the cane at all times when riding up the arena; if it is dropped, the rider must pick it up and continue the race. The cane has a rubber stopper 10 cm from the hook, for safety, to stop the fish travelling up the cane and hitting the rider's fingers. If the fish goes up the cane, the rider must stop and get it back onto the hook before going on.",
            FishingDiagram),

        new Entry("Rosette Row", "Other",
            "Five-rider race: hook rosettes from a bin with a cane and hand them to Number Five to hang on a gibbet, spelling P G U K.",
            "Race requires five members. A litter bin containing four coloured rosettes, each with a large letter in the centre and a ring, is placed on the Centre Line. The rosettes are laid out in a square: Blue (letter P) at 12 o'clock, Red (G) at 3 o'clock, Green (U) at 6 o'clock and Yellow (K) at 9 o'clock. Number Five stands 3 m behind the Changeover Line facing the Start/Finish Line, holding a Gibbet with the hooks facing sideways and open to Number Five's right. All four riders form up mounted at the Start/Finish End. Number One has a cane with a small hook on one end. On the signal to start, Number One rides to the bin, hooks any rosette and continues over the Changeover Line to Number Five. Number Five unhooks the rosette and secures it on the correct hook of the Gibbet. From Number Five's side the order is, left to right, Yellow K, Green U, Red G, Blue P; looking up the arena from the Start/Finish Line it reads, left to right, Blue P, Red G, Green U, Yellow K, spelling P G U K. Number One must remain behind the Changeover Line until Number Five has placed the rosette correctly, then returns over the Start/Finish Line and hands the cane to Number Two. Numbers Two, Three and Four complete the race in the same way. If a rosette is placed on the wrong hook, the rider must stay, or come back over the Changeover Line, while Number Five corrects it. If Number Five knocks off a rosette after the changeover has been completed and the rider has crossed back into the field of play, Number Five may replace it on the Gibbet without the rider needing to re-cross the Changeover Line. The winning team is the one whose Number Four is first across the Start/Finish Line with all four rosettes on the Gibbet in the correct order. If a rider drops a rosette, they may pick it up, mounted or dismounted, before replacing it on the hook of the cane. If a rosette is dropped while handing over to Number Five, Number Five may pick it up and put it on the Gibbet. The rosette should be on the hook at all times when riding up the arena; if it is dropped, the rider must pick it up and continue the race. The cane has a rubber stopper 10 cm from the hook, for safety, to stop the rosette travelling up the cane and hitting the rider's fingers. If the rosette goes up the cane, the rider must stop and get it back onto the hook before going on.",
            RosetteRowDiagram),

        // ── Zone 2026 sponsored aliases ───────────────────────────────────
        new Entry("Hollywood Bowl Boule & Bucket", "Zone 2026 · Ball",
            "Zone 2026 sponsored name for Boule and Bucket.",
            "Four plastic boules for each team are placed within a marked circle 3 m behind the Changeover Line. A row of Buckets, one for each team, is placed across the Centre Line. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a boule, rides to the Centre Line and places the boule in the bucket. They continue to the Changeover End, dismount, pick up a boule, remount and return to hand it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way in succession, with Number Four placing the last boule in the bucket on the way back. When dismounted, the rider must hold the pony by the nearer rein throughout. The winning team is the one whose Number Four is first over the Start/Finish Line with five boules in the bucket. Line Stewards replace boules knocked out of the circle, if it is safe to do so. If a boule is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that boule must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            BouleAndBucketDiagram),

        new Entry("Hollywood Bowl Old Sock", "Zone 2026 · Equipment",
            "Zone 2026 sponsored name for Old Sock.",
            "At the Changeover End each team has four socks sewn into balls about the size of a fist, placed on the ground in a circle 3 m beyond the Changeover Line. A row of buckets, one for each team, is placed across the Centre Line. All four riders form up behind the Start/Finish Line. On the signal to start, Number One, carrying a sock, rides to their team's bucket and drops the sock into it. They ride towards the Changeover Line, dismount, pick up a sock, remount and return over the Start/Finish Line to hand it to Number Two. Numbers Two, Three and Four complete the race in the same way in succession, with Number Four dropping the last sock into the bucket on the way back. The winning team is the one whose Number Four is first over the Start/Finish Line with five socks in their bucket. Socks knocked out of the circle should be replaced by the Line Steward concerned. If a sock is knocked into the field of play and cannot be retrieved safely by the Line Steward, the rider collecting that sock must pick it up and carry it over the Changeover Line before mounting and continuing the race.",
            OldSockDiagram),

        new Entry("Tally Ho Farm Ball & Socket", "Zone 2026 · Ball",
            "Zone 2026 sponsored name for Ball and Socket.",
            "A line of four Ball Cones is placed level with Poles 1, 2, 3 and 4, with a tennis ball on top of each cone. A Bending Pole topped with a Socket Board with four sockets, each large enough to hold a tennis ball, is placed 3 m beyond the Changeover Line. Number One, carrying a tennis ball, rides to the Changeover End and places it in one of the sockets. Number One then rides back down the arena to the Start/Finish End, collecting a tennis ball from any Ball Cone on the way and handing it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One in turn. The winning team is the one whose Number Four is first over the Start/Finish Line carrying the last tennis ball. If a rider makes a genuine attempt to place a ball in a socket and drops it, they may dismount and place it in the socket dismounted. If, in placing their ball, a rider knocks out a ball that a previous rider has placed in the Socket Board, they must replace it, mounted or dismounted.",
            BallAndSocketDiagram),

        new Entry("PGSports UK Shopping Spree", "Zone 2026 · Other",
            "Zone 2026 sponsored name for the Shopping Spree race.",
            "A Bending Pole topped with a Penny Dish fitted with four hooks on the underside is erected on the Centre Line. The Penny Dish contains four pennies stacked on top of each other. In line with the Bending Pole, a Table is placed 3 m behind the Changeover Line, with a bucket on it holding four evenly spaced, branded canvas shopping bags. Each bag contains a Junior Bottle, which forms part of the equipment. Number Five stands behind the Table. All four riders are at the Start/Finish End. On the signal to start, Number One rides to the Centre Line, collects a penny from the Penny Dish, rides over the Changeover Line and hands the penny to Number Five. Number Five places the penny in the bucket and hands one of the shopping bags to Number One (the bag may be taken out of the bucket before the penny goes in). Number One then rides back to the Penny Dish and hangs the bag on any of the hooks on the underside of the dish, then rides back across the Start/Finish Line. Both handles of the bag must be hung on the same hook. Numbers Two, Three and Four repeat the actions of Number One, each using a separate hook for their bag. If, after a rider has crossed the Start/Finish Line, a handle becomes unhooked, the rider who is in the field of play at the time may replace the handle on the hook and continue the race. The winning team is the one whose Number Four is first over the Start/Finish Line with four pennies in the bucket and four branded shopping bags hanging correctly on the hooks under the Penny Dish.",
            ShoppingSpreeDiagram),

        new Entry("STRUK Pole (JV)", "Zone 2026 · Letter Pole",
            "Junior five-member version of STRUK Pole: Number Five hands out the cartons from a bucket on a table behind the Changeover Line.",
            "Junior version (requires five members). A Bending Pole is placed on the Centre Line. In a marked circle 3 m behind the Changeover Line is a Table, and on the Table is a Bucket containing seven individually marked cartons lettered S, T, R, U, K and two blanks. Number Five stands behind the Table. All four riders are mounted at the Start/Finish End. On the signal to start, Number One, carrying a blank carton, rides to the pole and slots it over the pole. They continue to the Changeover End, collect a blank carton from Number Five, ride down the arena and slot it over the pole, then ride back to the Changeover End, collect the other blank carton from Number Five, ride down the arena and hand it to Number Two. Number Two slots the blank carton, collects the carton marked K from Number Five and slots it, then collects the carton marked U and hands it to Number Three behind the Start/Finish Line. Number Three slots the U, collects R from Number Five and slots it, then collects T and hands it to Number Four. Number Four slots the T, collects S from Number Five, slots it and crosses the Start/Finish Line. The winning team is the one whose Number Four is first over the Start/Finish Line with all eight cartons on the pole, reading from top to bottom S, T, R, U, K, blank, blank, blank. Cartons placed in the wrong order, or the wrong way up, must be corrected by the rider concerned; the narrow neck of each carton is the top. Number Five must remain behind the Table at the Changeover End. They may move to retrieve a piece of dropped equipment but must return to their position behind the Table before continuing their role in the race.",
            StrukPoleJvDiagram),

        new Entry("Spell EGUK (JV)", "Zone 2026 · Spelling",
            "Junior version of Spell EGUK: four letter cards are hung one at a time by Number Five on a post with four hooks.",
            "Junior version. A Table is placed on the Centre Line with four cards (20 cm square) on it, showing the letters E, G, U and K on one side and K, U, G and E on the other, placed side by side and separately spaced. Number Five stands 3 m behind the Changeover Line holding a post about 1.22 m (4 ft) high, which has a cross bar with four hooks facing towards Number Five. All four riders line up at the Start/Finish End. On the signal to start, Number One rides to the Table, picks up any one card, continues over the Changeover Line, hands the card to Number Five and waits behind the Changeover Line until Number Five has hung it on the correct hook, so that when viewed from the Start/Finish Line the cards read E G U K. Number One then returns across the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One. The winning team is the one whose Number Four is first across the Start/Finish Line with all four cards on the hooks spelling E G U K when viewed from the Start/Finish Line. Number Five must remain behind the Changeover Line at all times. If a rider drops a card, they may retrieve it mounted or dismounted, but cards must always be handed to Number Five from the mounted position. Cards knocked off the Table at the Centre Line can be replaced in any order.",
            Spell4CardsJuniorDiagram),

        new Entry("Spell EGUK", "Zone 2026 · Spelling",
            "Zone 2026 name for Spell E G U K.",
            "A Table is placed on the Centre Line with eight cards (20 cm square) on it, placed randomly in pairs. Four of the cards have the letters E, G, U and K on one side and K, U, G and E on the other; the other four have an EGUK logo on each side. Number Five stands 3 m behind the Changeover Line holding a Gibbet, which has two crossbars each with four hooks screwed to the lower edge. On the signal to start, Number One rides to the Table, picks up any two cards, rides to the Gibbet and hangs them on the correct hooks so that, viewed from the Start/Finish Line, the top row of hooks spells EGUK and the bottom row of hooks shows four EGUK logos. Number One then rides down the arena and across the Start/Finish Line. Numbers Two, Three and Four repeat the actions of Number One. The winning team is the one whose Number Four is first back across the Start/Finish Line with all eight cards on the hooks, EGUK on the top row and four logos on the bottom row. Number Five must hold the Gibbet upright. They may not help physically but can speak to any of the riders. Dropped letters may be retrieved dismounted but must always be hung from the mounted position.",
            Spell8CardsDiagram),

        new Entry("EGUK Mug Changes", "Zone 2026 · Mug",
            "Zone 2026 sponsored name for Mug Changes.",
            "Four Bending Poles are placed in a line 7 to 9 m apart, with mugs on Poles 2 and 4. Numbers One and Three are mounted at the Start/Finish End; Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One, carrying a mug, rides to Pole 1 and places the mug on it, collects the mug from Pole 2 and places it on Pole 3, then collects the mug from Pole 4 and hands it to Number Two behind the Changeover Line. Number Two places the mug on Pole 4, collects the mug from Pole 3 and places it on Pole 2, then collects the mug from Pole 1 and hands it to Number Three behind the Start/Finish Line. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four is first over the Start/Finish Line, mounted and carrying the mug, with mugs on Poles 2 and 4. Any pole that is knocked over must be corrected by the rider concerned and be upright at the end of the race. Mugs must be placed on each pole in the correct order. If a mug falls or is missed, the rider must replace it before continuing. If the next mug has already been moved, the rider must first put that mug back on the correct pole and then correct the first error.",
            MugChangesDiagram),

        new Entry("2 Flag", "Zone 2026 · Flag",
            "Zone 2026 name for Two Flag.",
            "There are two Flag Cones for each team, placed level with Poles 1 and 4, with a flag in the Flag Cone level with Pole 4. Numbers One and Three are at the Start/Finish End and Numbers Two and Four are at the Changeover End. On the signal to start, Number One, carrying a flag, rides to the Flag Cone level with Pole 1 and places the flag in it. They then ride to the Flag Cone level with Pole 4, take out the flag and hand it to Number Two behind the Changeover Line. Number Two places the flag in the Flag Cone level with Pole 4, rides to the Flag Cone level with Pole 1, takes out the flag and hands it to Number Three behind the Start/Finish Line. Numbers Three and Four repeat the actions of Numbers One and Two respectively. Flag Cones that are knocked over must be set up immediately by the rider concerned. If a flag comes off its cane, the cane alone may be used to complete the race. The winning team is the one whose Number Four is first over the Start/Finish Line carrying a flag.",
            TwoFlagDiagram),

        new Entry("5 Flag", "Zone 2026 · Flag",
            "Zone 2026 name for Five Flag.",
            "A Flag Cone is placed 3 m behind the Changeover Line and another on the Centre Line. Each team has five flags on canes: four are in the Flag Cone on the Centre Line and one is carried by Number One at the start. On the signal to start, Number One rides to the Changeover End and places the flag they are carrying in the Flag Cone, then rides back, takes a flag from the Flag Cone on the Centre Line and hands it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way, up and down the arena in succession, so that the team has placed four flags in the Flag Cone at the far end of the arena and Number Four finishes over the Start/Finish Line mounted and carrying the fifth flag. If a Flag Cone is knocked over, the rider must put it up again, replacing any flags that were in it. If a rider takes more than one flag from the Flag Cone, they must replace the surplus. They may dismount to correct mistakes. The winning team is the one whose Number Four is first over the Start/Finish Line carrying a flag. If a flag comes off its cane, the cane may be used to complete the race. On windy days rubber bands can be used to keep the flags furled.",
            FiveFlagDiagram),

        // ── Area 2026 sponsored aliases + junior variants ─────────────────
        new Entry("5 Mug", "Area 2026 · Mug",
            "Area 2026 name for Five Mug – Pole Specific.",
            "Five Bending Poles are put up 7 to 9 m apart, with Pole 1 the nearest to the Start/Finish Line. A Table is placed 3 m behind the Changeover Line. All four riders are mounted at the Start/Finish End. The team has five mugs. Four of them, one of which carries the EGUK logo, are placed inverted on the Table, with the EGUK mug at 8 o'clock (left front) looking from the Start/Finish Line; the fifth is carried by Number One. On the signal to start, Number One rides to Pole 2 and places the mug inverted on top, rides to the Table, picks up any mug except the EGUK mug and rides back to hand it to Number Two behind the Start/Finish Line. Number Two does the same on Pole 3, Number Three on Pole 4, with Number Three picking up the remaining mug without the logo. Number Four places the mug inverted on Pole 5, rides to the Table, picks up the EGUK mug, rides back down the arena, places it on top of Pole 1 and rides across the Start/Finish Line. The winning team is the one whose Number Four is first over the Start/Finish Line with a mug on each pole and the EGUK mug on Pole 1. Riders may ride straight and need not bend through the poles. Any mug knocked off the Table must be replaced inverted by the rider concerned; the EGUK mug may be replaced inverted anywhere on the Table.",
            FiveMugDiagram),

        new Entry("2 Mug", "Area 2026 · Mug",
            "Area 2026 name for Two Mug.",
            "Four Bending Poles are placed in a line 7 to 9 m apart, with mugs on Poles 1 and 3. Numbers One and Three are mounted at the Start/Finish End; Numbers Two and Four are mounted at the Changeover End. On the signal to start, Number One rides down the arena, moves the mug from Pole 1 to Pole 2, then the mug from Pole 3 to Pole 4, and rides across the Changeover Line. Number Two rides back down the arena, moves the mug from Pole 4 to Pole 3, then the mug from Pole 2 to Pole 1, and crosses the Start/Finish Line. Number Three repeats the actions of Number One and Number Four repeats the actions of Number Two. The winning team is the one whose Number Four crosses the Start/Finish Line first with mugs on Poles 1 and 3. Mugs must be placed on each pole in the correct order. If a mug falls or is missed, the rider must replace it before continuing. If the next mug has already been moved, the rider must first put that mug back on the correct pole and then correct the first error.",
            TwoMugDiagram),

        new Entry("PGUK Pyramid", "Area 2026 · Equipment",
            "Area 2026 name for Pyramid – PGUK Version.",
            "A Table is placed on the Centre Line and another 3 m behind the Changeover Line. On the second Table are four unstacked plastic boxes, each weighing 500 g, with a printed letter on each side. Viewed from the Start/Finish Line they are placed K front right, U back right, G back left and P front left. On the signal to start, Number One rides to the Table behind the Changeover Line, collects the box marked K and rides to place it on the Table on the Centre Line. Number One then returns across the Start/Finish Line. Number Two rides to the Table behind the Changeover Line, collects the box marked U and stacks it on the previous box on the Centre Line Table, then returns across the Start/Finish Line. Number Three (collecting G) and Number Four (collecting P) complete the race in the same way. The winning team is the one whose Number Four is first over the Start/Finish Line with all four boxes stacked on the Centre Line Table, spelling P G U K from the top. After collecting a box, the rider may adjust the stack by hand or with the box, before or after placing their box on the stack. If a Table is knocked over or a box falls, the rider concerned may dismount to replace them. At the Changeover End the boxes may be replaced in any order but must be placed side by side, not on top of each other. At the Centre Line Table the boxes must be stacked upright and in the correct order. Line Stewards will only signal once an incorrect box has been placed on the Centre Line Table.",
            PyramidDiagram),

        new Entry("PGUK Pyramid (junior version)", "Area 2026 · Equipment",
            "Junior version of PGUK Pyramid: the four boxes start stacked on the table behind the Changeover Line.",
            "Junior version. A Table is placed on the Centre Line and another 3 m behind the Changeover Line. On the second Table are four plastic boxes, each weighing 500 g, with a printed letter on each side, stacked on top of each other and spelling K U G P from the top. On the signal to start, Number One rides across the Changeover Line, collects the box marked K and rides to place it on the Table on the Centre Line. Number One then returns across the Start/Finish Line. Number Two collects the box marked U and stacks it on the previous box on the Centre Line Table, then returns across the Start/Finish Line. Numbers Three and Four, collecting G and P respectively, complete the race in the same way. The winning team is the one whose Number Four is first over the Start/Finish Line with all four boxes stacked on the Centre Line Table, spelling P G U K from the top. After collecting a box, the rider may adjust the stack by hand or with the box, before or after placing their box on the stack. If the Centre Line Table is knocked over or a box falls, the rider concerned may dismount to replace them. The boxes must be stacked upright and in the correct order. If the Table behind the Changeover Line is knocked over, or a box is knocked off it, the rider must, if necessary, put the Table back in its correct place and replace any boxes. Line Stewards will only signal once an incorrect box has been placed on the Centre Line Table. In the five-member version, Number Five stands behind the Table behind the Changeover Line and must not encroach down either side of it. The boxes start unstacked, placed K front right, U back right, G back left and P front left as viewed from the Start/Finish Line, and Number Five hands each rider their box when they cross the Changeover Line. If the Table is knocked over or Number Five drops a box, they may collect it but must, if necessary, put the Table back in its correct place and stand behind it before handing the box over. If Number Five knocks a box off the Table while the rider is in the field of play, the rider must return over the Changeover Line and wait until it is replaced or, if it has already been replaced, cross the line and continue. If the rider has already placed their box on the Centre Line Table, they must pick it up, return over the Changeover Line and wait for the fallen box to be replaced before continuing. Boxes on the Changeover Table must be placed side by side, not on top of each other.",
            PyramidDiagram),

        new Entry("Hollywood Bowl Bottle", "Area 2026 · Bottle",
            "Area 2026 sponsored name for Bottle.",
            "There are two Tables for each team: one on the Centre Line and the other 3 m beyond the Changeover Line. On the table beyond the Changeover Line is a plastic 750 ml Bottle filled with sand or similar to weigh 500 g. On the signal to start, Number One, carrying a similar bottle, rides to the Table on the Centre Line, places the bottle upright on it, rides to the Changeover End, picks up the bottle from the Table there and returns to hand it to Number Two behind the Start/Finish Line. Number Two rides to the Table at the Changeover End, places the bottle upright on it, then rides back down the arena, collecting the bottle from the Table on the Centre Line on the way and handing it to Number Three behind the Start/Finish Line. Number Three repeats the actions of Number One, ending by handing the bottle to Number Four. Number Four repeats the actions of Number Two. The winning team is the one whose Number Four crosses the Start/Finish Line first, mounted and carrying the bottle. Any bottle or table that is knocked over must be replaced upright.",
            BottleDiagram),

        new Entry("Hollywood Bowl Bottle (junior version)", "Area 2026 · Bottle",
            "Junior version of Hollywood Bowl Bottle, with a smaller, lighter bottle.",
            "Junior version. There are two Tables for each team: one on the Centre Line and the other 3 m beyond the Changeover Line. On the table beyond the Changeover Line is a plastic 500 ml Bottle filled with sand or similar to weigh 440 g. On the signal to start, Number One, carrying a similar bottle, rides to the Table on the Centre Line, places the bottle upright on it, rides to the Changeover End, picks up the bottle from the Table there and returns to hand it to Number Two behind the Start/Finish Line. Number Two rides to the Table at the Changeover End, places the bottle upright on it, then rides back down the arena, collecting the bottle from the Table on the Centre Line on the way and handing it to Number Three behind the Start/Finish Line. Number Three repeats the actions of Number One, ending by handing the bottle to Number Four. Number Four repeats the actions of Number Two. The winning team is the one whose Number Four crosses the Start/Finish Line first, mounted and carrying the bottle. Any bottle or table that is knocked over must be replaced upright.",
            BottleDiagram),

        new Entry("Old Sock (junior version)", "Area 2026 · Equipment",
            "Junior version of Old Sock: the four socks wait in a penny dish on a pole behind the Changeover Line.",
            "A Bending Pole topped with a Penny Dish containing four socks is placed 3 m behind the Changeover Line. A row of buckets, one for each team, is placed across the Centre Line. All four riders form up at the Start/Finish End. On the signal to start, Number One, carrying a sock, rides to their team's bucket and drops the sock into it. They then continue over the Changeover Line, collect a sock from the Penny Dish and return across the Start/Finish Line to hand it to Number Two. Numbers Two, Three and Four complete the race in the same way in succession, with Number Four dropping the last sock into the bucket on the way back. If a sock or socks are knocked out of the Penny Dish, they must be replaced by the rider concerned. The winning team is the one whose Number Four is first over the Start/Finish Line with five socks in their bucket.",
            OldSockJvDiagram),

        new Entry("Old Sock (JV)", "Area 2026 · Equipment",
            "Junior version of Old Sock: the four socks wait in a penny dish on a pole behind the Changeover Line.",
            "A Bending Pole topped with a Penny Dish containing four socks is placed 3 m behind the Changeover Line. A row of buckets, one for each team, is placed across the Centre Line. All four riders form up at the Start/Finish End. On the signal to start, Number One, carrying a sock, rides to their team's bucket and drops the sock into it. They then continue over the Changeover Line, collect a sock from the Penny Dish and return across the Start/Finish Line to hand it to Number Two. Numbers Two, Three and Four complete the race in the same way in succession, with Number Four dropping the last sock into the bucket on the way back. If a sock or socks are knocked out of the Penny Dish, they must be replaced by the rider concerned. The winning team is the one whose Number Four is first over the Start/Finish Line with five socks in their bucket.",
            OldSockJvDiagram),

        new Entry("EGUK 5 Flag", "Area 2026 · Flag",
            "Area 2026 sponsored name for 5 Flag / Five Flag.",
            "A Flag Cone is placed 3 m behind the Changeover Line and another on the Centre Line. Each team has five flags on canes: four are in the Flag Cone on the Centre Line and one is carried by Number One at the start. On the signal to start, Number One rides to the Changeover End and places the flag they are carrying in the Flag Cone, then rides back, takes a flag from the Flag Cone on the Centre Line and hands it to Number Two behind the Start/Finish Line. Numbers Two, Three and Four complete the course in the same way, up and down the arena in succession, so that the team has placed four flags in the Flag Cone at the far end of the arena and Number Four finishes over the Start/Finish Line mounted and carrying the fifth flag. If a Flag Cone is knocked over, the rider must put it up again, replacing any flags that were in it. If a rider takes more than one flag from the Flag Cone, they must replace the surplus. They may dismount to correct mistakes. The winning team is the one whose Number Four is first over the Start/Finish Line carrying a flag. If a flag comes off its cane, the cane may be used to complete the race. On windy days rubber bands can be used to keep the flags furled.",
            FiveFlagDiagram),
    };

    /// <summary>Every built-in race: the team races, then their Pairs and Individual versions.</summary>
    public static readonly Entry[] All =
    [
        .. Core,
        .. RaceLibraryVariants.All.Select(v => new Entry(
            v.Name,
            $"{Core.First(c => c.Name == v.BaseName).Category} · {(v.Format == Entities.SectionFormat.Pairs ? "Pairs" : "Individual")}",
            v.Summary,
            v.Rules,
            v.DiagramJson)),
    ];
}
